/** Miniature principale (cartes du catalogue). */
export const getThumb = (model: string): string | undefined =>
  PHONE_PHOTOS[model]?.thumb[0];

/** Visuel principal pleine taille (fiche detaillee). */
export const getPhoto = (model: string): string | undefined =>
  PHONE_PHOTOS[model]?.webp[0];

/** Toutes les images d'un modele (coloris + vues de dos/profil). */
export const getPhotos = (model: string): string[] =>
  PHONE_PHOTOS[model]?.webp ?? [];

/** Repli : meme fichier servi par GitHub au lieu de jsDelivr. */
export const toRaw = (url: string): string => url.replace(PHOTO_CDN, PHOTO_RAW);

/** Repli PNG a partir d'une URL WebP. */
export const toPng = (url: string): string =>
  url.replace('/webp/', '/').replace('/thumb/', '/').replace(/\.webp$/, '.png');
